"""Panda Valley game HTML asset"""

PANDA_VALLEY_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">\n  <title>Panda Valley: Bamboo Forest Adventure</title>\n  <style>\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n      user-select: none;\n      -webkit-user-select: none;\n      touch-action: none;\n    }\n    body, html {\n      width: 100%;\n      height: 100%;\n      overflow: hidden;\n      background: #06140b;\n      font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\n      color: #fff;\n    }\n    #game-container {\n      position: relative;\n      width: 100vw;\n      height: 100vh;\n      overflow: hidden;\n      background: #081c10;\n    }\n    canvas {\n      display: block;\n      width: 100%;\n      height: 100%;\n    }\n    /* Modern HUD overlay */\n    #hud {\n      position: absolute;\n      top: env(safe-area-inset-top, 12px);\n      left: 0;\n      width: 100%;\n      padding: 12px 18px;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      pointer-events: none;\n      z-index: 10;\n    }\n    .hud-left, .hud-right {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n    .hud-card {\n      background: rgba(15, 32, 22, 0.75);\n      backdrop-filter: blur(8px);\n      -webkit-backdrop-filter: blur(8px);\n      border: 1px solid rgba(74, 222, 128, 0.3);\n      padding: 6px 14px;\n      border-radius: 999px;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      box-shadow: 0 4px 16px rgba(0,0,0,0.3);\n      font-size: 13px;\n      font-weight: 700;\n      color: #f0fdf4;\n      pointer-events: auto;\n    }\n    .hud-card .icon {\n      font-size: 15px;\n    }\n    .hud-btn {\n      cursor: pointer;\n      pointer-events: auto;\n      transition: transform 0.15s ease, background 0.15s ease;\n    }\n    .hud-btn:active {\n      transform: scale(0.92);\n    }\n    /* Virtual Mobile Controls */\n    #mobile-controls {\n      position: absolute;\n      bottom: max(16px, env(safe-area-inset-bottom, 16px));\n      left: 0;\n      width: 100%;\n      padding: 0 20px;\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-end;\n      pointer-events: none;\n      z-index: 20;\n    }\n    .d-pad {\n      display: flex;\n      gap: 12px;\n      pointer-events: auto;\n    }\n    .action-pad {\n      display: flex;\n      gap: 14px;\n      pointer-events: auto;\n    }\n    .touch-btn {\n      width: 64px;\n      height: 64px;\n      border-radius: 50%;\n      background: rgba(22, 48, 32, 0.65);\n      backdrop-filter: blur(6px);\n      -webkit-backdrop-filter: blur(6px);\n      border: 2px solid rgba(74, 222, 128, 0.4);\n      color: #fff;\n      font-size: 22px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      box-shadow: 0 6px 20px rgba(0,0,0,0.35);\n      cursor: pointer;\n      transition: transform 0.08s ease, background 0.08s ease, border-color 0.08s ease;\n    }\n    .touch-btn:active, .touch-btn.active {\n      background: rgba(34, 197, 94, 0.45);\n      border-color: #4ade80;\n      transform: scale(0.92);\n      box-shadow: 0 0 20px rgba(74, 222, 128, 0.6);\n    }\n    .touch-btn.btn-jump {\n      width: 72px;\n      height: 72px;\n      background: rgba(34, 197, 94, 0.25);\n      border-color: rgba(74, 222, 128, 0.7);\n    }\n    .touch-btn.btn-dash {\n      width: 60px;\n      height: 60px;\n      background: rgba(59, 130, 246, 0.25);\n      border-color: rgba(96, 165, 250, 0.7);\n    }\n    /* Modal screens (Game Over, Victory, Pause) */\n    .modal-overlay {\n      position: absolute;\n      inset: 0;\n      background: rgba(6, 20, 11, 0.85);\n      backdrop-filter: blur(10px);\n      -webkit-backdrop-filter: blur(10px);\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      z-index: 50;\n      opacity: 0;\n      pointer-events: none;\n      transition: opacity 0.3s ease;\n      padding: 24px;\n      text-align: center;\n    }\n    .modal-overlay.active {\n      opacity: 1;\n      pointer-events: auto;\n    }\n    .modal-card {\n      background: rgba(18, 42, 28, 0.95);\n      border: 2px solid rgba(74, 222, 128, 0.5);\n      border-radius: 24px;\n      padding: 32px 28px;\n      max-width: 360px;\n      width: 100%;\n      box-shadow: 0 20px 50px rgba(0,0,0,0.6), 0 0 30px rgba(74,222,128,0.2);\n      animation: modalPop 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) both;\n    }\n    @keyframes modalPop {\n      0% { transform: scale(0.85); opacity: 0; }\n      100% { transform: scale(1); opacity: 1; }\n    }\n    .modal-title {\n      font-size: 26px;\n      font-weight: 800;\n      color: #4ade80;\n      margin-bottom: 8px;\n    }\n    .modal-sub {\n      font-size: 14px;\n      color: #a7f3d0;\n      margin-bottom: 20px;\n      line-height: 1.4;\n    }\n    .stats-row {\n      display: flex;\n      justify-content: space-around;\n      margin-bottom: 24px;\n      padding: 12px;\n      background: rgba(6, 20, 11, 0.6);\n      border-radius: 14px;\n      border: 1px solid rgba(74, 222, 128, 0.2);\n    }\n    .stat-item {\n      display: flex;\n      flex-direction: column;\n      gap: 4px;\n    }\n    .stat-label {\n      font-size: 11px;\n      text-transform: uppercase;\n      letter-spacing: 0.5px;\n      color: #6ee7b7;\n    }\n    .stat-val {\n      font-size: 20px;\n      font-weight: 800;\n      color: #fff;\n    }\n    .btn-start {\n      width: 100%;\n      padding: 14px 20px;\n      border-radius: 16px;\n      border: none;\n      background: linear-gradient(135deg, #22c55e, #15803d);\n      color: #fff;\n      font-size: 16px;\n      font-weight: 700;\n      cursor: pointer;\n      box-shadow: 0 8px 24px rgba(34, 197, 94, 0.4);\n      transition: transform 0.15s ease, box-shadow 0.15s ease;\n    }\n    .btn-start:active {\n      transform: scale(0.96);\n    }\n    @media (min-width: 820px) {\n      .touch-btn { opacity: 0.45; }\n      .touch-btn:hover { opacity: 0.9; }\n    }\n  </style>\n</head>\n<body>\n  <div id="game-container">\n    <canvas id="gameCanvas"></canvas>\n\n    <!-- Top Status HUD -->\n    <div id="hud">\n      <div class="hud-left">\n        <div class="hud-card">\n          <span class="icon">🎋</span>\n          <span id="score-display">0</span>\n        </div>\n        <div class="hud-card">\n          <span class="icon">❤️</span>\n          <span id="lives-display">3</span>\n        </div>\n      </div>\n      <div class="hud-right">\n        <div class="hud-card">\n          <span class="icon">⚡</span>\n          <span id="stamina-display">100%</span>\n        </div>\n        <div class="hud-card hud-btn" id="pause-btn" onclick="togglePause()">\n          <span id="pause-icon">⏸️</span>\n        </div>\n      </div>\n    </div>\n\n    <!-- Touch Mobile Controls -->\n    <div id="mobile-controls">\n      <div class="d-pad">\n        <div class="touch-btn" id="btn-left">◀</div>\n        <div class="touch-btn" id="btn-right">▶</div>\n      </div>\n      <div class="action-pad">\n        <div class="touch-btn btn-dash" id="btn-dash">💨</div>\n        <div class="touch-btn btn-jump" id="btn-jump">🔺</div>\n      </div>\n    </div>\n\n    <!-- Start / Game Over Modal -->\n    <div class="modal-overlay active" id="game-modal">\n      <div class="modal-card">\n        <div style="font-size: 48px; margin-bottom: 8px;">🐼</div>\n        <div class="modal-title" id="modal-title">Panda Valley</div>\n        <div class="modal-sub" id="modal-sub">Run, jump, and dash through the mystical bamboo valley! Collect golden bamboo shoots and jade dew.</div>\n        <div class="stats-row" id="modal-stats" style="display: none;">\n          <div class="stat-item">\n            <span class="stat-label">Score</span>\n            <span class="stat-val" id="final-score">0</span>\n          </div>\n          <div class="stat-item">\n            <span class="stat-label">Best</span>\n            <span class="stat-val" id="best-score">0</span>\n          </div>\n        </div>\n        <button class="btn-start" id="start-btn" onclick="startGame()">Play Adventure</button>\n      </div>\n    </div>\n  </div>\n\n  <script>\n    // --- Synthesized Web Audio Sound Engine ---\n    const AudioEngine = {\n      ctx: null,\n      init() {\n        if (!this.ctx) {\n          const AudioContext = window.AudioContext || window.webkitAudioContext;\n          if (AudioContext) this.ctx = new AudioContext();\n        }\n      },\n      beep(freq, duration, type = \'sine\', sweep = 0) {\n        if (!this.ctx) return;\n        try {\n          const osc = this.ctx.createOscillator();\n          const gain = this.ctx.createGain();\n          osc.type = type;\n          osc.frequency.setValueAtTime(freq, this.ctx.currentTime);\n          if (sweep !== 0) {\n            osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + sweep), this.ctx.currentTime + duration);\n          }\n          gain.gain.setValueAtTime(0.18, this.ctx.currentTime);\n          gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + duration);\n          osc.connect(gain);\n          gain.connect(this.ctx.destination);\n          osc.start();\n          osc.stop(this.ctx.currentTime + duration);\n        } catch(e) {}\n      },\n      jump() { this.beep(280, 0.16, \'square\', 240); },\n      doubleJump() { this.beep(480, 0.18, \'sine\', 320); },\n      dash() { this.beep(160, 0.22, \'triangle\', 180); },\n      pickup() { this.beep(640, 0.12, \'sine\', 480); },\n      gem() { this.beep(880, 0.22, \'triangle\', 440); },\n      hit() { this.beep(120, 0.25, \'sawtooth\', -80); },\n      gameOver() {\n        this.beep(220, 0.2, \'sawtooth\', -60);\n        setTimeout(() => this.beep(160, 0.35, \'sawtooth\', -80), 220);\n      }\n    };\n\n    // --- Game Engine ---\n    const canvas = document.getElementById(\'gameCanvas\');\n    const ctx = canvas.getContext(\'2d\');\n\n    let W = canvas.width = window.innerWidth;\n    let H = canvas.height = window.innerHeight;\n\n    window.addEventListener(\'resize\', () => {\n      W = canvas.width = window.innerWidth;\n      H = canvas.height = window.innerHeight;\n      groundY = H - 90;\n    });\n\n    let groundY = H - 90;\n    let isPlaying = false;\n    let isPaused = false;\n    let score = 0;\n    let lives = 3;\n    let stamina = 100;\n    let highScore = parseInt(localStorage.getItem(\'panda_valley_hi\') || \'0\', 10);\n    let cameraX = 0;\n\n    // Keys state\n    const keys = { left: false, right: false, jump: false, dash: false };\n\n    // Player Object (Bao Bao the Panda)\n    const panda = {\n      x: 100,\n      y: groundY - 45,\n      w: 42,\n      h: 44,\n      vx: 0,\n      vy: 0,\n      speed: 5.5,\n      jumpForce: -13.5,\n      isGrounded: false,\n      jumpsLeft: 2,\n      facing: 1,\n      isRolling: false,\n      rollTimer: 0,\n      invulnerable: 0,\n      animTime: 0\n    };\n\n    // Level Elements\n    let platforms = [];\n    let items = [];\n    let obstacles = [];\n    let particles = [];\n    let ambientLeaves = [];\n\n    function initLeaves() {\n      ambientLeaves = [];\n      for (let i = 0; i < 35; i++) {\n        ambientLeaves.push({\n          x: Math.random() * W,\n          y: Math.random() * H,\n          size: Math.random() * 6 + 3,\n          speedY: Math.random() * 0.8 + 0.5,\n          speedX: Math.random() * 1 - 0.2,\n          rot: Math.random() * Math.PI * 2,\n          rotSpeed: (Math.random() - 0.5) * 0.04,\n          alpha: Math.random() * 0.4 + 0.3,\n          color: Math.random() > 0.3 ? \'#86efac\' : \'#fde047\'\n        });\n      }\n    }\n    initLeaves();\n\n    function spawnWorldChunk(startX, length) {\n      platforms.push({ x: startX, y: groundY, w: length, h: 120, type: \'ground\' });\n\n      let px = startX + 160;\n      while (px < startX + length - 160) {\n        const py = groundY - (Math.random() * 120 + 70);\n        const pw = Math.random() * 80 + 90;\n        platforms.push({ x: px, y: py, w: pw, h: 18, type: \'bamboo\' });\n\n        if (Math.random() > 0.25) {\n          items.push({\n            x: px + pw / 2,\n            y: py - 26,\n            type: Math.random() > 0.8 ? \'dewdrop\' : \'bamboo\',\n            collected: false\n          });\n        }\n\n        if (Math.random() > 0.5) {\n          obstacles.push({\n            x: px + pw + 60,\n            y: groundY - 28,\n            w: 32,\n            h: 28,\n            type: Math.random() > 0.5 ? \'spikes\' : \'boulder\'\n          });\n        }\n\n        px += pw + Math.random() * 140 + 120;\n      }\n    }\n\n    function initLevel() {\n      cameraX = 0;\n      platforms = [];\n      items = [];\n      obstacles = [];\n      particles = [];\n\n      spawnWorldChunk(0, 1800);\n      spawnWorldChunk(1800, 2200);\n\n      panda.x = 120;\n      panda.y = groundY - 50;\n      panda.vx = 0;\n      panda.vy = 0;\n      panda.jumpsLeft = 2;\n      panda.invulnerable = 0;\n    }\n\n    function drawBackground() {\n      const sky = ctx.createLinearGradient(0, 0, 0, H);\n      sky.addColorStop(0, \'#04170d\');\n      sky.addColorStop(0.55, \'#0b351e\');\n      sky.addColorStop(1, \'#1b5e39\');\n      ctx.fillStyle = sky;\n      ctx.fillRect(0, 0, W, H);\n\n      ctx.fillStyle = \'rgba(7, 36, 20, 0.55)\';\n      ctx.beginPath();\n      ctx.moveTo(0, H);\n      for (let x = 0; x <= W + 60; x += 60) {\n        const my = H * 0.42 + Math.sin((x + cameraX * 0.15) * 0.004) * 80 + Math.cos(x * 0.007) * 40;\n        ctx.lineTo(x, my);\n      }\n      ctx.lineTo(W, H);\n      ctx.closePath();\n      ctx.fill();\n\n      ctx.fillStyle = \'rgba(15, 66, 36, 0.45)\';\n      for (let bx = -60; bx < W + 80; bx += 85) {\n        const sway = Math.sin(Date.now() * 0.0015 + bx) * 6;\n        ctx.fillRect(bx + sway - (cameraX * 0.35 % 85), H * 0.25, 12, H * 0.75);\n      }\n\n      ambientLeaves.forEach(leaf => {\n        leaf.y += leaf.speedY;\n        leaf.x += leaf.speedX + Math.sin(Date.now() * 0.002 + leaf.rot) * 0.6;\n        leaf.rot += leaf.rotSpeed;\n        if (leaf.y > H + 20) leaf.y = -20;\n        if (leaf.x > W + 20) leaf.x = -20;\n        if (leaf.x < -20) leaf.x = W + 20;\n\n        ctx.save();\n        ctx.translate(leaf.x, leaf.y);\n        ctx.rotate(leaf.rot);\n        ctx.fillStyle = leaf.color;\n        ctx.globalAlpha = leaf.alpha;\n        ctx.beginPath();\n        ctx.ellipse(0, 0, leaf.size, leaf.size * 0.45, 0, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.restore();\n      });\n    }\n\n    function drawPlatforms() {\n      platforms.forEach(p => {\n        const sx = p.x - cameraX;\n        if (sx + p.w < -100 || sx > W + 100) return;\n\n        if (p.type === \'ground\') {\n          ctx.fillStyle = \'#22c55e\';\n          ctx.fillRect(sx, p.y, p.w, 14);\n          const earth = ctx.createLinearGradient(0, p.y + 14, 0, p.y + p.h);\n          earth.addColorStop(0, \'#14532d\');\n          earth.addColorStop(1, \'#052e16\');\n          ctx.fillStyle = earth;\n          ctx.fillRect(sx, p.y + 14, p.w, p.h);\n        } else {\n          ctx.fillStyle = \'#4ade80\';\n          ctx.beginPath();\n          ctx.roundRect(sx, p.y, p.w, p.h, 8);\n          ctx.fill();\n          ctx.strokeStyle = \'#15803d\';\n          ctx.lineWidth = 2.5;\n          ctx.stroke();\n\n          ctx.fillStyle = \'#166534\';\n          for (let rx = sx + 22; rx < sx + p.w - 15; rx += 28) {\n            ctx.fillRect(rx, p.y + 2, 4, p.h - 4);\n          }\n        }\n      });\n    }\n\n    function drawItems() {\n      items.forEach(it => {\n        if (it.collected) return;\n        const sx = it.x - cameraX;\n        if (sx < -40 || sx > W + 40) return;\n\n        const floatY = it.y + Math.sin(Date.now() * 0.005 + it.x) * 5;\n\n        if (it.type === \'bamboo\') {\n          ctx.save();\n          ctx.translate(sx, floatY);\n          ctx.shadowColor = \'#facc15\';\n          ctx.shadowBlur = 12;\n          ctx.fillStyle = \'#facc15\';\n          ctx.beginPath();\n          ctx.moveTo(0, -14);\n          ctx.lineTo(10, 8);\n          ctx.lineTo(-10, 8);\n          ctx.closePath();\n          ctx.fill();\n          ctx.fillStyle = \'#84cc16\';\n          ctx.fillRect(-3, 0, 6, 8);\n          ctx.restore();\n        } else {\n          ctx.save();\n          ctx.translate(sx, floatY);\n          ctx.shadowColor = \'#38bdf8\';\n          ctx.shadowBlur = 14;\n          ctx.fillStyle = \'#38bdf8\';\n          ctx.beginPath();\n          ctx.arc(0, 0, 9, 0, Math.PI * 2);\n          ctx.fill();\n          ctx.fillStyle = \'#ffffff\';\n          ctx.beginPath();\n          ctx.arc(-2, -2, 3, 0, Math.PI * 2);\n          ctx.fill();\n          ctx.restore();\n        }\n      });\n    }\n\n    function drawObstacles() {\n      obstacles.forEach(ob => {\n        const sx = ob.x - cameraX;\n        if (sx < -50 || sx > W + 50) return;\n\n        if (ob.type === \'spikes\') {\n          ctx.fillStyle = \'#ef4444\';\n          ctx.beginPath();\n          ctx.moveTo(sx, ob.y + ob.h);\n          ctx.lineTo(sx + ob.w / 2, ob.y);\n          ctx.lineTo(sx + ob.w, ob.y + ob.h);\n          ctx.closePath();\n          ctx.fill();\n        } else {\n          ctx.fillStyle = \'#64748b\';\n          ctx.beginPath();\n          ctx.arc(sx + ob.w / 2, ob.y + ob.h / 2, ob.w / 2, 0, Math.PI * 2);\n          ctx.fill();\n          ctx.strokeStyle = \'#334155\';\n          ctx.lineWidth = 2.5;\n          ctx.stroke();\n        }\n      });\n    }\n\n    function drawPanda() {\n      const sx = panda.x - cameraX;\n      ctx.save();\n      ctx.translate(sx + panda.w / 2, panda.y + panda.h / 2);\n\n      if (panda.invulnerable > 0 && Math.floor(Date.now() / 80) % 2 === 0) {\n        ctx.globalAlpha = 0.4;\n      }\n\n      if (panda.facing === -1) {\n        ctx.scale(-1, 1);\n      }\n\n      if (panda.isRolling) {\n        ctx.rotate((panda.animTime * 15) % (Math.PI * 2));\n        ctx.fillStyle = \'#ffffff\';\n        ctx.beginPath();\n        ctx.arc(0, 0, 20, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.fillStyle = \'#18181b\';\n        ctx.beginPath();\n        ctx.arc(-10, -6, 7, 0, Math.PI * 2);\n        ctx.arc(10, -6, 7, 0, Math.PI * 2);\n        ctx.arc(0, 12, 9, 0, Math.PI * 2);\n        ctx.fill();\n      } else {\n        const bob = Math.sin(panda.animTime * 10) * 2;\n\n        ctx.fillStyle = \'#18181b\';\n        ctx.beginPath();\n        ctx.arc(-14, -18 + bob, 6, 0, Math.PI * 2);\n        ctx.arc(14, -18 + bob, 6, 0, Math.PI * 2);\n        ctx.fill();\n\n        ctx.fillStyle = \'#ffffff\';\n        ctx.beginPath();\n        ctx.ellipse(0, 2 + bob, 18, 16, 0, 0, Math.PI * 2);\n        ctx.fill();\n\n        ctx.fillStyle = \'#18181b\';\n        ctx.beginPath();\n        ctx.ellipse(-7, -4 + bob, 4.5, 3.5, 0.2, 0, Math.PI * 2);\n        ctx.ellipse(7, -4 + bob, 4.5, 3.5, -0.2, 0, Math.PI * 2);\n        ctx.fill();\n\n        ctx.fillStyle = \'#ffffff\';\n        ctx.beginPath();\n        ctx.arc(-6, -5 + bob, 1.5, 0, Math.PI * 2);\n        ctx.arc(8, -5 + bob, 1.5, 0, Math.PI * 2);\n        ctx.fill();\n\n        ctx.fillStyle = \'#0f172a\';\n        ctx.beginPath();\n        ctx.ellipse(0, 1 + bob, 2.5, 1.8, 0, 0, Math.PI * 2);\n        ctx.fill();\n\n        ctx.fillStyle = \'rgba(244, 114, 182, 0.45)\';\n        ctx.beginPath();\n        ctx.arc(-12, 1 + bob, 3.5, 0, Math.PI * 2);\n        ctx.arc(12, 1 + bob, 3.5, 0, Math.PI * 2);\n        ctx.fill();\n\n        ctx.fillStyle = \'#18181b\';\n        const legOffset = Math.sin(panda.animTime * 12) * 5;\n        ctx.beginPath();\n        ctx.arc(-10, 16 + (panda.isGrounded ? legOffset : 0), 5, 0, Math.PI * 2);\n        ctx.arc(10, 16 - (panda.isGrounded ? legOffset : 0), 5, 0, Math.PI * 2);\n        ctx.fill();\n      }\n\n      ctx.restore();\n\n      particles.forEach((p, idx) => {\n        p.x += p.vx;\n        p.y += p.vy;\n        p.alpha -= p.fade;\n        if (p.alpha <= 0) {\n          particles.splice(idx, 1);\n          return;\n        }\n        ctx.fillStyle = p.color;\n        ctx.globalAlpha = p.alpha;\n        ctx.beginPath();\n        ctx.arc(p.x - cameraX, p.y, p.size, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.globalAlpha = 1;\n      });\n    }\n\n    function spawnDust(x, y, color = \'#a7f3d0\') {\n      for (let i = 0; i < 5; i++) {\n        particles.push({\n          x: x,\n          y: y,\n          vx: (Math.random() - 0.5) * 3,\n          vy: -Math.random() * 2,\n          size: Math.random() * 4 + 2,\n          color: color,\n          alpha: 0.8,\n          fade: 0.04\n        });\n      }\n    }\n\n    function update() {\n      if (!isPlaying || isPaused) return;\n\n      let moveDir = 0;\n      if (keys.left) moveDir -= 1;\n      if (keys.right) moveDir += 1;\n\n      if (moveDir !== 0) {\n        panda.facing = moveDir;\n        panda.vx = moveDir * (panda.isRolling ? panda.speed * 1.6 : panda.speed);\n        panda.animTime += 0.05;\n      } else {\n        panda.vx *= 0.78;\n        if (Math.abs(panda.vx) < 0.1) panda.vx = 0;\n      }\n\n      if (keys.dash && !panda.isRolling && stamina >= 25) {\n        panda.isRolling = true;\n        panda.rollTimer = 22;\n        stamina = Math.max(0, stamina - 28);\n        AudioEngine.dash();\n        spawnDust(panda.x + panda.w / 2, panda.y + panda.h, \'#60a5fa\');\n      }\n\n      if (panda.isRolling) {\n        panda.rollTimer--;\n        panda.animTime += 0.1;\n        if (panda.rollTimer <= 0) {\n          panda.isRolling = false;\n        }\n      }\n\n      if (stamina < 100) stamina = Math.min(100, stamina + 0.25);\n      document.getElementById(\'stamina-display\').innerText = Math.round(stamina) + \'%\';\n\n      panda.vy += 0.65;\n      if (panda.vy > 14) panda.vy = 14;\n\n      panda.x += panda.vx;\n      panda.y += panda.vy;\n\n      panda.isGrounded = false;\n      platforms.forEach(p => {\n        if (\n          panda.x + panda.w > p.x &&\n          panda.x < p.x + p.w &&\n          panda.y + panda.h >= p.y &&\n          panda.y + panda.h <= p.y + 24 &&\n          panda.vy >= 0\n        ) {\n          panda.y = p.y - panda.h;\n          panda.vy = 0;\n          panda.isGrounded = true;\n          panda.jumpsLeft = 2;\n        }\n      });\n\n      if (keys.jump) {\n        if (panda.jumpsLeft > 0) {\n          panda.vy = panda.jumpForce;\n          panda.jumpsLeft--;\n          if (panda.jumpsLeft === 1) AudioEngine.jump();\n          else AudioEngine.doubleJump();\n          spawnDust(panda.x + panda.w / 2, panda.y + panda.h);\n        }\n        keys.jump = false;\n      }\n\n      const targetCamX = panda.x - W * 0.35;\n      cameraX += (targetCamX - cameraX) * 0.1;\n      if (cameraX < 0) cameraX = 0;\n\n      const lastPlatform = platforms[platforms.length - 1];\n      if (lastPlatform && lastPlatform.x + lastPlatform.w - cameraX < W * 2) {\n        spawnWorldChunk(lastPlatform.x + lastPlatform.w, 2000);\n      }\n\n      items.forEach(it => {\n        if (it.collected) return;\n        if (\n          Math.hypot(panda.x + panda.w / 2 - it.x, panda.y + panda.h / 2 - it.y) < 32\n        ) {\n          it.collected = true;\n          if (it.type === \'bamboo\') {\n            score += 100;\n            AudioEngine.pickup();\n            spawnDust(it.x, it.y, \'#facc15\');\n          } else {\n            score += 250;\n            stamina = Math.min(100, stamina + 40);\n            AudioEngine.gem();\n            spawnDust(it.x, it.y, \'#38bdf8\');\n          }\n          document.getElementById(\'score-display\').innerText = score;\n        }\n      });\n\n      if (panda.invulnerable > 0) {\n        panda.invulnerable--;\n      } else {\n        obstacles.forEach(ob => {\n          if (\n            panda.x + panda.w > ob.x + 4 &&\n            panda.x < ob.x + ob.w - 4 &&\n            panda.y + panda.h > ob.y + 4 &&\n            panda.y < ob.y + ob.h\n          ) {\n            if (panda.isRolling) {\n              score += 150;\n              AudioEngine.pickup();\n              spawnDust(ob.x + ob.w / 2, ob.y + ob.h / 2, \'#fbbf24\');\n              ob.y = 99999;\n            } else {\n              lives--;\n              panda.invulnerable = 60;\n              panda.vy = -8;\n              panda.vx = -panda.facing * 6;\n              AudioEngine.hit();\n              document.getElementById(\'lives-display\').innerText = lives;\n              if (lives <= 0) {\n                gameOver();\n              }\n            }\n          }\n        });\n      }\n\n      if (panda.y > H + 50) {\n        lives--;\n        document.getElementById(\'lives-display\').innerText = lives;\n        if (lives > 0) {\n          panda.x = cameraX + 120;\n          panda.y = groundY - 60;\n          panda.vy = 0;\n          panda.invulnerable = 60;\n        } else {\n          gameOver();\n        }\n      }\n    }\n\n    function render() {\n      ctx.clearRect(0, 0, W, H);\n      drawBackground();\n      drawPlatforms();\n      drawObstacles();\n      drawItems();\n      drawPanda();\n\n      update();\n      requestAnimationFrame(render);\n    }\n    requestAnimationFrame(render);\n\n    function startGame() {\n      AudioEngine.init();\n      score = 0;\n      lives = 3;\n      stamina = 100;\n      document.getElementById(\'score-display\').innerText = \'0\';\n      document.getElementById(\'lives-display\').innerText = \'3\';\n      document.getElementById(\'stamina-display\').innerText = \'100%\';\n      document.getElementById(\'game-modal\').classList.remove(\'active\');\n      initLevel();\n      isPlaying = true;\n      isPaused = false;\n    }\n\n    function gameOver() {\n      isPlaying = false;\n      AudioEngine.gameOver();\n      if (score > highScore) {\n        highScore = score;\n        localStorage.setItem(\'panda_valley_hi\', highScore);\n      }\n      document.getElementById(\'modal-title\').innerText = \'Run Complete!\';\n      document.getElementById(\'modal-sub\').innerText = \'Bao Bao rested in the bamboo glade.\';\n      document.getElementById(\'final-score\').innerText = score;\n      document.getElementById(\'best-score\').innerText = highScore;\n      document.getElementById(\'modal-stats\').style.display = \'flex\';\n      document.getElementById(\'start-btn\').innerText = \'Play Again\';\n      document.getElementById(\'game-modal\').classList.add(\'active\');\n    }\n\n    function togglePause() {\n      if (!isPlaying) return;\n      isPaused = !isPaused;\n      document.getElementById(\'pause-icon\').innerText = isPaused ? \'▶️\' : \'⏸️\';\n    }\n\n    window.addEventListener(\'keydown\', e => {\n      AudioEngine.init();\n      if (e.code === \'ArrowLeft\' || e.code === \'KeyA\') keys.left = true;\n      if (e.code === \'ArrowRight\' || e.code === \'KeyD\') keys.right = true;\n      if (e.code === \'Space\' || e.code === \'ArrowUp\' || e.code === \'KeyW\') keys.jump = true;\n      if (e.code === \'ShiftLeft\' || e.code === \'ShiftRight\' || e.code === \'ArrowDown\' || e.code === \'KeyS\') keys.dash = true;\n    });\n\n    window.addEventListener(\'keyup\', e => {\n      if (e.code === \'ArrowLeft\' || e.code === \'KeyA\') keys.left = false;\n      if (e.code === \'ArrowRight\' || e.code === \'KeyD\') keys.right = false;\n      if (e.code === \'ShiftLeft\' || e.code === \'ShiftRight\' || e.code === \'ArrowDown\' || e.code === \'KeyS\') keys.dash = false;\n    });\n\n    function setupTouch(id, keyName) {\n      const el = document.getElementById(id);\n      if (!el) return;\n      const activate = e => {\n        e.preventDefault();\n        AudioEngine.init();\n        keys[keyName] = true;\n        el.classList.add(\'active\');\n      };\n      const deactivate = e => {\n        e.preventDefault();\n        keys[keyName] = false;\n        el.classList.remove(\'active\');\n      };\n      el.addEventListener(\'touchstart\', activate, { passive: false });\n      el.addEventListener(\'touchend\', deactivate, { passive: false });\n      el.addEventListener(\'touchcancel\', deactivate, { passive: false });\n      el.addEventListener(\'mousedown\', activate);\n      el.addEventListener(\'mouseup\', deactivate);\n      el.addEventListener(\'mouseleave\', deactivate);\n    }\n\n    setupTouch(\'btn-left\', \'left\');\n    setupTouch(\'btn-right\', \'right\');\n    setupTouch(\'btn-jump\', \'jump\');\n    setupTouch(\'btn-dash\', \'dash\');\n  </script>\n</body>\n</html>\n'
